:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --focus: #f5b700;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg);
  background-image: linear-gradient(45deg, #1a1a2e 25%, #16213e 25%, #16213e 50%, #1a1a2e 50%, #1a1a2e 75%, #16213e 75%, #16213e 100%);
  background-size: 8px 8px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.app {
  width: 100%;
  max-width: 480px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.mode-switch {
  display: flex;
  gap: 8px;
  width: 100%;
}

.mode-btn {
  flex: 1;
  padding: 12px 8px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  color: var(--muted);
  background: transparent;
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
}

.mode-btn:hover {
  background: var(--border);
  color: var(--text);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translateY(2px);
}

.mode-btn.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.timer-display {
  font-size: 4.5rem;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 4px 4px 0 #000;
  line-height: 1;
  padding: 8px 0;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
}

.btn {
  flex: 1;
  padding: 16px 12px;
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 #000;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.btn-primary:hover {
  background: #ff5c7a;
}

.btn-secondary {
  background: var(--border);
  color: var(--text);
}

.btn-secondary:hover {
  background: #1a4a7a;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #000;
}

.hint {
  font-size: 0.875rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    gap: 16px;
  }
  .timer-display {
    font-size: 3.5rem;
  }
  .title {
    font-size: 1.25rem;
  }
  .mode-btn, .btn {
    font-size: 0.875rem;
    padding: 12px 8px;
  }
  .hint {
    font-size: 0.75rem;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

let mode = 'work';
let remaining = WORK_TIME;
let running = false;
let timerId = null;
let endTime = 0;

const timerDisplay = document.getElementById('timerDisplay');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workModeBtn = document.getElementById('workModeBtn');
const breakModeBtn = document.getElementById('breakModeBtn');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(remaining);
}

function setMode(newMode) {
  if (running) {
    stopTimer();
  }
  mode = newMode;
  remaining = mode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
  workModeBtn.classList.toggle('active', mode === 'work');
  breakModeBtn.classList.toggle('active', mode === 'break');
  workModeBtn.setAttribute('aria-pressed', mode === 'work');
  breakModeBtn.setAttribute('aria-pressed', mode === 'break');
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function tick() {
  const now = Date.now();
  const diff = Math.max(0, Math.round((endTime - now) / 1000));
  remaining = diff;
  updateDisplay();
  if (remaining <= 0) {
    stopTimer();
    if (mode === 'work') {
      setMode('break');
    } else {
      setMode('work');
    }
  }
}

function startTimer() {
  if (running) return;
  running = true;
  endTime = Date.now() + remaining * 1000;
  timerId = setInterval(tick, 250);
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
}

function stopTimer() {
  running = false;
  clearInterval(timerId);
  timerId = null;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function toggleTimer() {
  if (running) {
    stopTimer();
  } else {
    startTimer();
  }
}

function resetTimer() {
  stopTimer();
  remaining = mode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

startPauseBtn.addEventListener('click', toggleTimer);
resetBtn.addEventListener('click', resetTimer);
workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

document.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    e.preventDefault();
    toggleTimer();
  } else if (e.key === 'r' || e.key === 'R') {
    resetTimer();
  }
});

updateDisplay();
